package ru.cherdakmd.chrdkguilds;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;

class GuildDuesTest {
    @TempDir Path dir;
    final UUID leader=UUID.randomUUID(),member=UUID.randomUUID();
    final long now=1_900_000_000_000L,day=GuildPeaceTerm.DAY;
    final GuildConfig config=GuildConfig.defaults();
    GuildStore store(){var s=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());var g=new Guild("one","FirstGuild","ONE",leader,now);g.addMember(member,GuildRank.MEMBER);s.add(g);return s;}
    GuildDuesService service(GuildStore s){return new GuildDuesService(s,config);}
    @Test void allBattleMembersIncludingLeaderOweTenButNotBeforeNextDay(){var s=store();for(var id:new UUID[]{leader,member}){assertFalse(service(s).daily(id,now,100).result().ok());var p=service(s).daily(id,now+day,100);assertEquals(10,p.debit());assertEquals(id,p.payer());}assertEquals(20,s.of(leader).treasury());}
    @Test void peacePaymentRemainsAdditionalAndOrdinaryDuesCannotUseTreasury(){var s=store();var g=s.of(leader);g.deposit(100);assertTrue(new GuildPeaceService(s).mode(new GuildFinance.Quote(),leader,GuildMode.PEACEFUL,now).ok());long due=g.duesTerm(member).dueAt();assertEquals(10,service(s).daily(member,due,10).debit());assertEquals(10,new GuildPeaceService(s).daily(member,g.peaceTerm(member).paidUntil(),10).debit());assertEquals(10,service(s).daily(leader,due,10).debit());}
    @Test void richTreasuryDoesNotPayItsOwnMembershipDues(){var s=store();s.of(leader).deposit(10000);assertEquals("dues-leader-grace",service(s).daily(leader,now+day,0).result().key());assertEquals(10000,s.of(leader).treasury());assertNotNull(s.of(member));}
    @Test void offlineCatchupIsExactAndRepeatedTickDoesNotChargeTwice(){var s=store();var p=service(s).daily(member,now+3*day,100);assertEquals(30,p.debit());assertEquals(30,s.of(member).treasury());assertFalse(service(s).daily(member,now+3*day,100).result().ok());}
    @Test void onlyLeaderCanSetMinimumAndDailyCooldownIsEnforced(){var s=store();assertEquals("not-leader",service(s).rate(member,20,now).key());assertEquals("dues-range",service(s).rate(leader,9,now).key());assertEquals("dues-range",service(s).rate(leader,1_000_001,now).key());assertTrue(service(s).rate(leader,20,now).ok());assertEquals("dues-cooldown",service(s).rate(leader,30,now+1).key());}
    @Test void alreadyAnnouncedInvoiceIsNotRepricedAndCatchupUsesNewFutureRate(){var s=store();assertTrue(service(s).rate(leader,25,now+day-1).ok());assertEquals(10,s.of(member).duesTerm(member).amount());var p=service(s).daily(member,now+3*day,100);assertEquals(60,p.debit());assertEquals(25,s.of(member).duesTerm(member).amount());}
    @Test void cannotChangeRateWhileAnyMemberIsOverdue(){var s=store();assertEquals("dues-settle-first",service(s).rate(leader,20,now+day).key());assertEquals(10,s.of(leader).duesRate());}
    @Test void partialCatchupDoesNotExtendGrace(){var s=store();long due=now+3*day;service(s).daily(member,due,0);long deadline=s.of(member).duesTerm(member).deadline();assertEquals(10,service(s).daily(member,due+1,10).debit());assertEquals(deadline,s.of(member).duesTerm(member).deadline());assertEquals("dues-auto-kick",service(s).daily(member,deadline,10).result().key());assertNull(s.of(member));}
    @Test void memberGetsOneDayThenRemovedEvenWithTreasuryMoney(){var s=store();s.of(leader).deposit(1000);long due=now+day;assertEquals("dues-member-grace",service(s).daily(member,due,0).result().key());assertNotNull(s.of(member));assertFalse(service(s).daily(member,due+day-1,0).result().ok());assertEquals("dues-auto-kick",service(s).daily(member,due+day,0).result().key());assertNull(s.of(member));assertNotNull(s.of(leader));assertFalse(s.peaceNotices(member).isEmpty());}
    @Test void leaderNonpaymentDissolvesWholeClanAndKeepsDurableNotices(){var s=store();s.of(leader).deposit(1000);service(s).daily(leader,now+day,0);assertEquals("dues-auto-disband",service(s).daily(leader,now+2*day,0).result().key());assertEquals(0,s.count());assertFalse(s.peaceNotices(member).isEmpty());}
    @Test void unknownBankDoesNotStartGraceOrEnforceExpiredGrace(){var s=store();assertEquals("finance-paused",service(s).daily(member,now+day,-1).result().key());assertEquals(0,s.of(member).duesTerm(member).graceSince());service(s).daily(member,now+day,0);assertEquals("finance-paused",service(s).daily(member,now+10*day,-1).result().key());assertNotNull(s.of(member));}
    @Test void fullRepaymentDuringGraceResetsGraceWithoutFreeDays(){var s=store();service(s).daily(member,now+day,0);assertEquals(10,service(s).daily(member,now+day+1,10).debit());assertEquals(0,s.of(member).duesTerm(member).graceSince());assertEquals(now+2*day,s.of(member).duesTerm(member).dueAt());}
    @Test void fullTreasuryPreservesEveryDiamondInCollectiveReserveAndRefillsOnSpend(){var s=store();var g=s.of(leader);g.deposit(Guild.MAX_TREASURY);assertEquals(10,service(s).daily(member,now+day,10).debit());assertEquals(10,g.duesReserve());assertEquals(Guild.MAX_TREASURY,g.treasury());var copy=s.detached(s.snapshotJson());assertEquals(10,copy.of(leader).duesReserve());g.withdraw(7);assertEquals(Guild.MAX_TREASURY,g.treasury());assertEquals(3,g.duesReserve());assertEquals(7,GuildFinance.treasurySpent(copy.of(leader),g));}
    @Test void restartPreservesTariffInvoiceGraceAndReserve(){var s=store();service(s).rate(leader,25,now);s.of(leader).deposit(Guild.MAX_TREASURY);service(s).daily(leader,now+day,10);service(s).daily(member,now+day,0);s.saveNow();var loaded=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());loaded.load();assertEquals(25,loaded.of(member).duesRate());assertEquals(s.of(member).duesTerm(member),loaded.of(member).duesTerm(member));assertEquals(10,loaded.of(member).duesReserve());}
    @Test void strictSchemaRejectsMissingTermsWrongOwnerAndTooLowAmounts(){var s=store();var json=com.google.gson.JsonParser.parseString(s.snapshotJson()).getAsJsonObject();var row=json.getAsJsonArray("guilds").get(0).getAsJsonObject();row.remove("dues-terms");String missing=json.toString();assertThrows(RuntimeException.class,()->s.detached(missing));json=com.google.gson.JsonParser.parseString(s.snapshotJson()).getAsJsonObject();row=json.getAsJsonArray("guilds").get(0).getAsJsonObject();row.addProperty("dues-rate",9);String broken=json.toString();assertThrows(RuntimeException.class,()->s.detached(broken));}
    @Test void oldSchemaGetsTransitionDayNotRetroactiveDues(){var s=store();var json=com.google.gson.JsonParser.parseString(s.snapshotJson()).getAsJsonObject();json.addProperty("version",2);var row=json.getAsJsonArray("guilds").get(0).getAsJsonObject();row.remove("dues-terms");row.remove("dues-rate");row.remove("dues-changed-at");row.remove("dues-reserve");long before=System.currentTimeMillis();var loaded=s.detached(json.toString());assertEquals(10,loaded.of(member).duesRate());assertTrue(loaded.of(member).duesTerm(member).dueAt()>=before+day);assertEquals(0,loaded.of(member).treasury());}
    @Test void migrationIsCommittedOnceAndRestartCannotResetFirstDeadline()throws Exception{var s=store();var json=com.google.gson.JsonParser.parseString(s.snapshotJson()).getAsJsonObject();json.addProperty("version",2);for(var element:json.getAsJsonArray("guilds")){var old=element.getAsJsonObject();for(String k:java.util.List.of("dues-terms","dues-rate","dues-changed-at","dues-reserve"))old.remove(k);}var source=new ru.cherdakmd.chrdkregister.api.PaidActionStore(dir);source.initializeValues(java.util.Map.of(GuildStore.FINANCE_KEY,json.toString()));var live=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());live.bind(source);long due=live.of(member).duesTerm(member).dueAt();assertEquals(4,com.google.gson.JsonParser.parseString(source.values().get(GuildStore.FINANCE_KEY)).getAsJsonObject().get("version").getAsInt());var reboot=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());reboot.bind(new ru.cherdakmd.chrdkregister.api.PaidActionStore(dir));assertEquals(due,reboot.of(member).duesTerm(member).dueAt());}
    @Test void cannotEscapeOverdueByLeavingKickingOrTransferringLeadership(){var s=store();var svc=new GuildService(config,s);assertEquals("dues-settle-first",svc.leave(member,now+day).key());assertEquals("dues-settle-first",svc.kick(leader,member,now+day).key());assertEquals("dues-settle-first",svc.transfer(leader,member,now+day).key());assertNotNull(s.of(member));assertEquals(leader,s.of(member).leader());}
    @Test void modeSwitchDoesNotResetDues(){var s=store();var quote=new GuildFinance.Quote();s.of(leader).deposit(100);var before=s.of(member).duesTerm(member);assertTrue(new GuildPeaceService(s).mode(quote,leader,GuildMode.PEACEFUL,now).ok());assertEquals(before,s.of(member).duesTerm(member));}
    @Test void creationChargesFirstDuesAndCreditsTreasuryBeforeAnythingIsPublished(){var s=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());var q=GuildFinance.preview(s,config,(svc,purse)->svc.create(purse,leader,"FirstGuild","ONE",now));assertTrue(q.result().ok());assertEquals(config.creationCost()+10,q.debit());assertEquals(0,s.count());var after=s.detached(q.domain()).of(leader);assertEquals(10,after.treasury());assertEquals(now+day,after.duesTerm(leader).dueAt());}
    @Test void battleJoinRequiresPurseAndChargesFirstDayAtVisibleClanRate(){var s=store();var svc=new GuildService(config,s);var outsider=UUID.randomUUID();service(s).rate(leader,25,now);assertTrue(svc.invite(leader,outsider,now).ok());assertEquals("dues-join-required",svc.accept(outsider,now).key());var q=GuildFinance.preview(s,config,(service,purse)->service.accept(purse,outsider,now));assertEquals(25,q.debit());assertNull(s.of(outsider));var after=s.detached(q.domain()).of(outsider);assertEquals(25,after.treasury());assertEquals(25,after.duesTerm(outsider).amount());}
    @Test void automaticDisbandSettlesActiveWarRatherThanDestroyingOpponentsStake(){var s=store();var other=UUID.randomUUID();var rival=new Guild("rival","RivalGuild","RIV",other,now);s.add(rival);var war=new GuildWar("war","one","rival",100,now);war.activate(now,10*day/1000);s.addWar(war);service(s).daily(leader,now+day,0);assertEquals("dues-auto-disband",service(s).daily(leader,now+2*day,0).result().key());assertEquals(200,rival.treasury());assertTrue(s.wars().isEmpty());}
    @Test void transactionBatchCapDoesNotStartGraceWhenWholeBalanceCoversCatchup(){var s=store();var g=s.of(member);g.duesRate(1_000_000,now);g.duesTerm(member,new GuildDuesTerm(now+day,0,1_000_000));assertEquals(1_000_000,service(s).daily(member,now+3*day,3_000_000).debit());assertEquals(0,g.duesTerm(member).graceSince());}
    @Test void downgradedSchemaCannotSilentlyDropCollectiveDuesReserve(){var s=store();s.of(leader).deposit(Guild.MAX_TREASURY);s.of(leader).creditDues(100);var json=com.google.gson.JsonParser.parseString(s.snapshotJson()).getAsJsonObject();json.addProperty("version",2);assertThrows(RuntimeException.class,()->s.detached(json.toString()));}
    @Test void duesWALRecoveryPublishesTreasuryAndPeriodExactlyOnceOffline()throws Exception{
        var seed=store();seed.saveNow();var source=new ru.cherdakmd.chrdkregister.api.PaidActionStore(dir);var live=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());live.bind(source);source.markRegistered();
        var bank=new ru.cherdakmd.chrdkregister.BankStore(dir.resolve("core"),java.util.logging.Logger.getAnonymousLogger());bank.load();bank.registerIncomeSource("guilds",source.lineage());bank.deposit(member,"Member",50);
        var copy=live.copy();var plan=service(copy).daily(member,now+day,50);assertEquals(10,plan.debit());
        var journal=new ru.cherdakmd.chrdkregister.api.ChargeJournal(dir,"guilds",source.lineage());String empty=new com.google.gson.Gson().toJson(new String[36]);
        var charge=journal.prepare(member,plan.debit(),plan.debit(),0,0,empty,empty,source.snapshot(),source.previewValue(GuildStore.FINANCE_KEY,copy.snapshotJson()));assertTrue(bank.settleCharge(charge));
        assertEquals(0,live.of(member).treasury());assertEquals(now+day,live.of(member).duesTerm(member).dueAt());
        var api=(ru.cherdakmd.chrdkregister.api.ChrdkRegisterApi)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{ru.cherdakmd.chrdkregister.api.ChrdkRegisterApi.class},(proxy,method,args)->{if(method.getName().equals("bankChargeStatus"))return bank.bankChargeStatus((ru.cherdakmd.chrdkregister.api.BankCharge)args[0]);throw new AssertionError("offline path: "+method.getName());});
        var restarted=new ru.cherdakmd.chrdkregister.api.PaidActionStore(dir);var replay=new ru.cherdakmd.chrdkregister.api.ChargeJournal(dir,"guilds",restarted.lineage());
        assertEquals(ru.cherdakmd.chrdkregister.api.ChargeRecovery.Decision.COMPLETE,ru.cherdakmd.chrdkregister.api.ChargeInventory.recover(replay,api,null,restarted));
        var boot=new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());boot.bind(restarted);assertEquals(10,boot.of(member).treasury());assertEquals(now+2*day,boot.of(member).duesTerm(member).dueAt());assertEquals(40,bank.balance(member));
        ru.cherdakmd.chrdkregister.api.ChargeInventory.recover(replay,api,null,restarted);assertEquals(10,boot.of(member).treasury());assertEquals(40,bank.balance(member));
    }

    @Test void changingCreationPriceDuringConfirmationRequiresFreshQuote(){
        assertTrue(GuildPeaceController.sameCreatePrice(280,GuildConfig.defaults()));
        var yaml=new org.bukkit.configuration.file.YamlConfiguration();yaml.set("general.creation-cost",400);
        var changed=GuildConfig.parse(yaml,java.util.logging.Logger.getAnonymousLogger());
        assertFalse(GuildPeaceController.sameCreatePrice(280,changed));assertTrue(GuildPeaceController.sameCreatePrice(410,changed));
    }

}
